mapper.sql:
WHERE 1=1

    AND a.person_name LIKE CONCAT('%', #{personName}, '%')


    AND a.month = #{month}


    AND a.classes = #{classes}


    AND a.id_card = #{idCard}

mapper.select:
SELECT DISTINCT sp.identity_card AS "key", COALESCE(wg.work_group_name, backup_wg.work_group_name) AS "value" FROM swm_person sp -- 原有关联（通过fms_worker关联） LEFT JOIN fms_worker w ON sp.identity_card = w.identity_code COLLATE utf8mb4_general_ci LEFT JOIN fms_work_group wg ON w.work_group_id = wg.id -- 备用关联（通过swm_person表中保存的team字段关联） LEFT JOIN fms_work_group backup_wg ON sp.team = backup_wg.id COLLATE utf8mb4_general_ci WHERE sp.identity_card IN
#{idCard}
AND sp.status = '0'
